  const handleCreateNewClientGroup = async (e: React.FormEvent) => {
    e.preventDefault();
    const rawCode = newClientForm.clientCode
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_]/g, '');
    const coupleLabel = newClientForm.coupleLabel.trim();
    if (!rawCode || !coupleLabel) {
      showToast('Kode grup client dan nama pasangan wajib diisi.');
      return;
    }
    const clientId = rawCode.startsWith('client-') ? rawCode : `client-${rawCode}`;
    const clientName = `Client ${rawCode.toUpperCase()} • ${coupleLabel}`;

    setIsCreatingClientGroup(true);
    try {
      const res = await fetch('/api/auth', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'CREATE_CLIENT_GROUP_USERS',
          clientId,
          clientCode: rawCode,
          clientName,
          coupleLabel,
          initialPassword: newClientForm.initialPassword.trim() || `${rawCode}12345`,
        }),
      });
      const json = await res.json();
      if (!res.ok || !json.success) {
        showToast(json.error || 'Gagal membuat grup client & 4 akun default.');
        return;
      }

      const newGroupItem: ClientGroupItem = {
        id: clientId,
        clientCode: rawCode.toUpperCase(),
        clientName,
        coupleLabel,
        packageTier: newClientForm.packageTier,
        status: 'ACTIVE',
        eventDate: newClientForm.eventDate || '2026-12-19',
        notes: newClientForm.notes.trim(),
        createdAt: new Date().toISOString(),
      };

      const mergedGroups = [
        ...effectiveClientGroups.filter((g) => g.id !== clientId),
        newGroupItem,
      ];

      const coupleParts = coupleLabel.split('&').map((p) => p.trim());
      const groomNamePart = coupleParts[0] || `Mempelai Pria (${rawCode.toUpperCase()})`;
      const brideNamePart = coupleParts[1] || `Mempelai Wanita (${rawCode.toUpperCase()})`;

      const existingWorkspaces = {
        ...(state.settings.clientWorkspaces || {}),
        ...(settingsForm.clientWorkspaces || {}),
      };

      if (!existingWorkspaces[clientId]) {
        existingWorkspaces[clientId] = {
          clientId,
          settings: {
            ...state.settings,
            siteTitle: 'My Event Planner',
            activeClientId: clientId,
            groomFullName: groomNamePart,
            groomNickname: groomNamePart.split(' ')[0] || groomNamePart,
            groomRankAndTitle: 'Putra Pertama',
            groomUnit: '',
            groomParents: `Keluarga Besar Bapak & Ibu (${groomNamePart})`,
            brideFullName: brideNamePart,
            brideNickname: brideNamePart.split(' ')[0] || brideNamePart,
            brideTitle: 'Putri Pertama',
            brideParents: `Keluarga Besar Bapak & Ibu (${brideNamePart})`,
            subtitle: `Pernikahan ${groomNamePart} & ${brideNamePart} • ${
              newClientForm.eventDate || '2026-12-19'
            }`,
            updatedAt: new Date().toISOString(),
            updatedBy: adminUser.username,
          },
          tasks: state.tasks.map((t, idx) => ({
            ...t,
            id: `tsk_${rawCode}_${idx + 1}`,
            done: false,
            status: 'BELUM',
            doneAt: '',
          })),
          guests: [],
          wishes: [],
          budgetItems: [],
          updatedAt: new Date().toISOString(),
        };
      }

      const nextSettings: WeddingSettings = {
        ...state.settings,
        ...settingsForm,
        clientGroups: mergedGroups,
        clientWorkspaces: existingWorkspaces,
        updatedBy: adminUser.username,
      };

      if (onSyncStateAndUser && json.data) {
        onSyncStateAndUser({
          ...json.data,
          settings: nextSettings,
        });
      }
      await commitImmediateSettings(nextSettings);

      setIsAddClientModalOpen(false);
      setSelectedClientGroupFilter(clientId);
      setNewClientForm({
        clientCode: '',
        coupleLabel: '',
        packageTier: 'ROYAL_VIP',
        eventDate: '2026-12-19',
        notes: 'Paket All-in-One Wedding Planner & Digital Invitation',
        initialPassword: '',
      });
      appendAuditLog({
        actor: adminUser.username,
        module: 'SUPERADMIN_CLIENT',
        action: 'TAMBAH',
        status: 'SUCCESS',
        summary: `Membuat Grup Client komersial baru "${clientName}" beserta 4 User Default otomatis`,
      });
      showToast(
        json.message ||
          `✓ Grup Client "${clientName}" & 4 Akun Default berhasil dibuat!`
      );
    } catch (err) {
      showToast(
        `Gagal membuat grup client: ${
          err instanceof Error ? err.message : String(err)
        }`
      );
    } finally {
      setIsCreatingClientGroup(false);
    }
  };

  const handleApproveAndProvisionOrder = async (
    tx: CommercialPaymentTransaction
  ) => {
    const cleanCouple = (
      tx.buyerCoupleName ||
      tx.buyerEmail?.split('@')[0] ||
      'Klien Baru'
    ).trim();
    const baseCode =
      cleanCouple
        .replace(/[^a-zA-Z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .toLowerCase()
        .slice(0, 14) || `klien_${Date.now().toString(36).slice(-4)}`;

    const existingGrp = effectiveClientGroups.find(
      (g) =>
        (tx.provisionedClientId && g.id === tx.provisionedClientId) ||
        (tx.orderId && g.notes?.includes(tx.orderId)) ||
        (tx.idempotencyKey && g.notes?.includes(tx.idempotencyKey))
    );
    const clientId =
      existingGrp?.id ||
      tx.provisionedClientId ||
      `client-${baseCode}-${Date.now().toString(36).slice(-3)}`;
    const clientCode = (
      existingGrp?.clientCode ||
      tx.provisionedClientCode ||
      baseCode
    ).toUpperCase();
    const lowerCode = clientCode.toLowerCase();
    const initialPassword =
      tx.provisionedInitialPassword || `${lowerCode}12345`;
    const clientName = existingGrp?.clientName || `Klien • ${cleanCouple}`;
    const nowIso = new Date().toISOString();

    let serverData: WeddingDatabaseSchema | null = null;
    try {
      const res = await fetch('/api/auth', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'CREATE_CLIENT_GROUP_USERS',
          clientId,
          clientCode: lowerCode,
          clientName,
          coupleLabel: cleanCouple,
          initialPassword,
        }),
      });
      const json = await res.json();
      if (res.ok && json.success && json.data) {
        serverData = json.data;
      }
    } catch {
      // Fallback to local state provisioning if server route is unreachable
    }

    const parts = cleanCouple.split('&').map((p) => p.trim());
    const groomPart = parts[0] || cleanCouple;
    const bridePart = parts[1] || 'Partner';

    const defaultFourUsers: AdminUser[] = [
      {
        id: `adm-${lowerCode}-pria`,
        username: `${lowerCode}_pria`,
        nama: `${groomPart} (Mempelai Pria)`,
        role: 'MEMPELAI_PRIA',
        jabatan: `Mempelai Pria • ${cleanCouple}`,
        email: `${lowerCode}.pria@meplanner.id`,
        password: initialPassword,
        isDefaultUser: true,
        clientId,
        clientName,
      },
      {
        id: `adm-${lowerCode}-wanita`,
        username: `${lowerCode}_wanita`,
        nama: `${bridePart} (Mempelai Wanita)`,
        role: 'MEMPELAI_WANITA',
        jabatan: `Mempelai Wanita • ${cleanCouple}`,
        email: `${lowerCode}.wanita@meplanner.id`,
        password: initialPassword,
        isDefaultUser: true,
        clientId,
        clientName,
      },
      {
        id: `adm-${lowerCode}-kel-pria`,
        username: `${lowerCode}_kel_pria`,
        nama: `Keluarga ${groomPart} (Pria)`,
        role: 'KELUARGA_PRIA',
        jabatan: `Keluarga Pria • ${cleanCouple}`,
        email: `${lowerCode}.kel.pria@meplanner.id`,
        password: initialPassword,
        isDefaultUser: true,
        clientId,
        clientName,
      },
      {
        id: `adm-${lowerCode}-kel-wanita`,
        username: `${lowerCode}_kel_wanita`,
        nama: `Keluarga ${bridePart} (Wanita)`,
        role: 'KELUARGA_WANITA',
        jabatan: `Keluarga Wanita • ${cleanCouple}`,
        email: `${lowerCode}.kel.wanita@meplanner.id`,
        password: initialPassword,
        isDefaultUser: true,
        clientId,
        clientName,
      },
    ];

    const baseUsers = serverData?.adminUsers?.length
      ? [...serverData.adminUsers]
      : [...(state.adminUsers || [])];
    for (const u of defaultFourUsers) {
      if (
        !baseUsers.some(
          (ex) => ex.username.toLowerCase() === u.username.toLowerCase()
        )
      ) {
        baseUsers.push(u);
      }
    }

    const newGroupItem: ClientGroupItem = {
      id: clientId,
      clientCode,
      clientName,
      coupleLabel: cleanCouple,
      packageTier:
        tx.packageTier === 'ROYAL VIP' ? 'ROYAL_VIP' : tx.packageTier,
      status: 'ACTIVE',
      eventDate: existingGrp?.eventDate || '2026-12-19',
      notes:
        existingGrp?.notes ||
        `Order ${tx.orderId} • ${tx.selectedThemeName || tx.packageName}`,
      createdAt: existingGrp?.createdAt || nowIso,
    };

    const mergedGroups = [
      ...effectiveClientGroups.filter((g) => g.id !== clientId),
      newGroupItem,
    ];

    const existingWorkspaces = {
      ...(state.settings.clientWorkspaces || {}),
      ...(settingsForm.clientWorkspaces || {}),
    };

    if (!existingWorkspaces[clientId]) {
      const effectiveEventType: EventCategoryType = tx.eventType || 'WEDDING';
      const dummyIdForEvent =
        effectiveEventType === 'BIRTHDAY'
          ? 'client-demo-birthday'
          : effectiveEventType === 'GRADUATION'
            ? 'client-demo-graduation'
            : effectiveEventType === 'MEETING'
              ? 'client-demo-meeting'
              : effectiveEventType === 'GALA_DINNER'
                ? 'client-demo-gala'
                : 'client-demo-wedding';
      const mappedTier: ShowcasePackageTier =
        tx.packageTier === 'STARTER'
          ? 'STARTER'
          : tx.packageTier === 'EXCLUSIVE'
            ? 'EXCLUSIVE'
            : 'ROYAL VIP';
      const baseTemplate = getShowcaseDummyClientState(
        dummyIdForEvent,
        mappedTier,
        tx.selectedThemeId
      );

      existingWorkspaces[clientId] = {
        clientId,
        settings: {
          ...baseTemplate.settings,
          activeClientId: clientId,
          eventType: effectiveEventType,
          groomFullName: groomPart,
          groomNickname: groomPart.split(' ')[0] || groomPart,
          brideFullName: bridePart,
          brideNickname: bridePart.split(' ')[0] || bridePart,
          subtitle: `${cleanCouple} • ${
            tx.selectedThemeName || baseTemplate.settings.subtitle
          }`,
          updatedAt: nowIso,
          updatedBy: adminUser.username,
        },
        tasks: baseTemplate.tasks.map((t, idx) => ({
          ...t,
          id: `tsk_${lowerCode}_${idx + 1}`,
          done: false,
          status: 'BELUM',
          doneAt: '',
        })),
        guests: [],
        wishes: [],
        budgetItems: [],
        updatedAt: nowIso,
      };
    }

    const updatedTx: CommercialPaymentTransaction = {
      ...tx,
      status: 'PAID_VERIFIED',
      verifiedBy: adminUser.username,
      verifiedAt: nowIso,
      provisionedClientId: clientId,
      provisionedClientCode: clientCode,
      provisionedInitialPassword: initialPassword,
      updatedAt: nowIso,
    };

    const nextPayments = effectivePayments.some((p) => p.id === tx.id)
      ? effectivePayments.map((p) => (p.id === tx.id ? updatedTx : p))
      : [updatedTx, ...effectivePayments];

    const nextSettings: WeddingSettings = {
      ...state.settings,
      ...settingsForm,
      clientGroups: mergedGroups,
      clientWorkspaces: existingWorkspaces,
      commercialPayments: nextPayments,
      updatedBy: adminUser.username,
    };

    setSettingsForm((prev) => ({
      ...prev,
      clientGroups: mergedGroups,
      clientWorkspaces: existingWorkspaces,
      commercialPayments: nextPayments,
    }));

    if (onSyncStateAndUser) {
      onSyncStateAndUser({
        ...(serverData || state),
        adminUsers: baseUsers,
        settings: nextSettings,
      });
    }
    await commitImmediateSettings(nextSettings);
    void upsertCommercialPaymentToSupabase(updatedTx);

    appendAuditLog({
      actor: adminUser.username,
      module: 'SUPERADMIN_PAYMENT',
      action: 'EDIT',
      status: 'SUCCESS',
      summary: `Menerima & mengaktifkan klien "${cleanCouple}" (${clientCode}) dari Order ${tx.orderId} beserta 4 akun login`,
    });
    showToast(
      `✓ Klien "${cleanCouple}" aktif! 4 akun (${lowerCode}_pria s/d kel_wanita • Sandi: ${initialPassword}) siap dikirim.`
    );
  };

  const handleDeleteClientGroup = (group: ClientGroupItem) => {
    if (group.id === 'client-utama' || group.id === 'client-demo') {
      showToast('Ruang kerja sistem (Klien Demo / Klien Utama) tidak dapat dihapus.');
      return;
    }
    requestConfirm({
      title: `Hapus Grup Client "${group.clientName}"?`,
      message: `Seluruh akun User Default & Panitia yang tergabung dalam grup "${group.clientName}" (${group.clientCode}) akan dihapus permanen dari sistem.`,
      confirmLabel: 'Ya, Hapus Grup Client',
      variant: 'danger',
      onConfirm: async () => {
        try {
          const res = await fetch('/api/auth', {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'DELETE_CLIENT_GROUP',
              clientId: group.id,
            }),
          });
          const json = await res.json();
          if (!res.ok || !json.success) {
            showToast(json.error || 'Gagal menghapus grup client.');
            return;
          }
          const nextGroups = effectiveClientGroups.filter(
            (g) => g.id !== group.id
          );
          const nextSettings: WeddingSettings = {
            ...state.settings,
            ...settingsForm,
            clientGroups: nextGroups,
            activeClientId:
              (settingsForm.activeClientId || state.settings.activeClientId) ===
              group.id
                ? 'client-utama'
                : settingsForm.activeClientId || state.settings.activeClientId,
            updatedBy: adminUser.username,
          };
          if (onSyncStateAndUser && json.data) {
            onSyncStateAndUser({
              ...json.data,
              settings: nextSettings,
            });
          }
          await commitImmediateSettings(nextSettings);
          if (selectedClientGroupFilter === group.id) {
            setSelectedClientGroupFilter('ALL');
          }
          appendAuditLog({
            actor: adminUser.username,
            module: 'SUPERADMIN_CLIENT',
            action: 'HAPUS',
            status: 'SUCCESS',
            summary: `Menghapus Grup Client "${group.clientName}" beserta seluruh akunnya`,
          });
          showToast(
            json.message || `Grup Client "${group.clientName}" berhasil dihapus.`
          );
        } catch {
          showToast('Gagal menghubungi server saat menghapus grup client.');
        }
      },
    });
  };

