                                    type="file"
                                    multiple
                                    accept="image/*,video/mp4,video/webm,video/quicktime,.mp4,.webm,.mov,.svg,.webp,.png,.jpg,.jpeg,.avif,.bmp,.tif,.tiff,.heic,.heif,.dng,.cr2,.cr3,.nef,.arw,.rw2,.orf,.raf"
                                    className="hidden"
